            # Fill the triangular-number pattern: even y in the near triangle,
            # and even x beyond its diagonal edge.
            if (x <= y and y % 2 == 0) or (x > y and x % 2 == 0):
                out[r][c] = 4
            else:
                out[r][c] = 0
    return out
